let parsed = {};
try {
  const text = input.response || input.text || input.content || "{}";
  const m = text.match(/\{[\s\S]*\}/);
  parsed = m ? JSON.parse(m[0]) : {};
} catch (e) { parsed = {}; }
return {
  ...input,
  documentType: parsed.documentType || "Other",
  documentDate: parsed.documentDate || ""
};
